import random, time, itertools
from problems import ExactCover, SubsetSum
from reduce import reduce

def solve_ec_dp(inst):
    u = inst["universe_size"]; full=(1<<u)-1
    masks=[]
    for s in inst["sets"]:
        mk=0
        for e in s: mk|=1<<e
        masks.append(mk)
    # DP over reachable covered masks (disjointness enforced)
    reach={0}
    for mk in masks:
        new=set()
        for c in reach:
            if c & mk == 0:
                new.add(c|mk)
        reach|=new
    return full in reach

def solve_ss(inst):
    t=inst["target"]
    if t<0: return False
    r={0}
    for a in inst["numbers"]:
        r |= {x+a for x in r}
    return t in r

rng=random.Random(999)
run=passed=0
# bigger random with DP solver
for _ in range(3000):
    u=rng.randint(0,9); m=rng.randint(0,12)
    sets=[[e for e in range(u) if rng.random()<0.4] for _ in range(m)]
    inst={"universe_size":u,"sets":sets}
    ExactCover.validate(inst)
    e=solve_ec_dp(inst)
    red=reduce(inst); SubsetSum.validate(red)
    g=solve_ss(red)
    run+=1
    if e==g: passed+=1
    else: print("FAIL",inst,red,e,g)

# duplicate-heavy structured cases
for _ in range(2000):
    u=rng.randint(1,6)
    base_sets=[]
    for _ in range(rng.randint(1,3)):
        base_sets.append([e for e in range(u) if rng.random()<0.5])
    sets=[]
    for _ in range(rng.randint(1,8)):
        sets.append(list(rng.choice(base_sets)))
    inst={"universe_size":u,"sets":sets}
    ExactCover.validate(inst)
    e=solve_ec_dp(inst); red=reduce(inst); g=solve_ss(red)
    run+=1
    if e==g: passed+=1
    else: print("FAIL dup",inst,red,e,g)

print("run",run,"passed",passed)

# performance / polynomial check
for u,m in [(200,50),(500,100),(1000,200)]:
    sets=[[e for e in range(u) if (e*7+j)%3==0] for j in range(m)]
    inst={"universe_size":u,"sets":sets}
    t0=time.time(); red=reduce(inst); dt=time.time()-t0
    print(f"u={u} m={m} reduce_time={dt:.3f}s target_bits={red['target'].bit_length()}")
EOF
python3 extra_checks.py"}

